            j-=1
        direct=has_any(text,['may disclose','may be disclosed','only to disclose','disclosed only to','restrict access','restrict disclosure','except in confidence'])
        child_permission=parent_permission and has_any(text,['only to such','only to employees','only to its employees'])
        roles=[]
        if 'employee' in text or 'staff' in text or 'personnel' in text:
            owner='controlled_entity' if has_any(text,['companies directly or indirectly owned or controlled','company controlled by','under common control']) else 'receiving_party'
