            else:
                exception_kind='none'
            atoms_add(out,['source_clause_atom',scope,segment.get('label',''),segment.get('parent',''),'disclosure_prohibition',raw],[segment.get('unit')])
            atoms_add(out,['source_disclosure_prohibition_atom',scope,segment.get('label',''),exception_kind,raw],[segment.get('unit')])
            if cross:
                atoms_add(out,['source_reference_atom',scope,segment.get('label',''),'disclosure_permission_cross_reference',raw],[segment.get('unit')])
                unresolved.append('Disclosure permission cross-reference remains unresolved in clause '+segment.get('label',''))
        i+=1","

