                        qualified = legal[left]
                        auth = authorizations.get(left, '')
                    combined = ['authorized_action_alternative', normal, qualified, auth]
                elif kind == 'or':
                    combined = ['action_alternative', legal[left], legal[right]]
                else:
                    unresolved.append('connector unresolved for ' + scope)
                    continue
                norm = ['disposal_obligation', ['receiving_party'], combined, lt, ['source_scoped_exception_set', raw]]
                compose_add(out, norm, support)
                emitted.add(left)
                emitted.add(right)
            elif lt is not None and rt is not None and (kind == 'and'):
                compose_add(out, ['disposal_obligation', ['receiving_party'], legal[left], lt, ['source_scoped_exception_set', actions[left].get('raw', '')]], support_map.get(left, []))
                compose_add(out, ['disposal_obligation', ['receiving_party'], legal[right], rt, ['source_scoped_exception_set', actions[right].get('raw', '')]], support_map.get(right, []))
                emitted.add(left)
                emitted.add(right)
            else:
                unresolved.append('trigger or connector composition unresolved for ' + scope)
        for action_id in ids:
            if action_id in emitted or action_id not in legal:
                continue
            data = actions[action_id]
            trigger = action_triggers.get(action_id)
            if trigger is not None:
                norm = ['disposal_obligation', ['receiving_party'], legal[action_id], trigger, ['source_scoped_exception_set', data.get('raw', '')]]
                compose_add(out, norm, support_map.get(action_id, []))
            else:
                unresolved.append('trigger unresolved for ' + action_id)
    return {'statements': out, 'complete': len(compose_unique(unresolved)) == 0, 'unresolved': compose_unique(unresolved)}","

","def pb_rows(value):
    if isinstance(value, list):
        return value
    if isinstance(value, dict):
        rows = value.get('answers')
        if isinstance(rows, list):
            return rows
        if isinstance(rows, dict):
            return list(rows.values())
        return list(value.values())
    return []","

","def pb_answer(rows, qid):
    for row in rows:
        if isinstance(row, dict) and row.get('id') == qid:
            return row
    return None","

","def pb_unique(values):
    out = []
    for value in values:
        if value not in out:
            out.append(value)
    return out","

","def pb_evidence(answer):
    ids = []
    quotes = []
    if not isinstance(answer, dict):
        return (ids, quotes)
    evidence = answer.get('evidence', [])
    if isinstance(evidence, dict):
        evidence = [evidence]
    for item in evidence:
        if isinstance(item, dict):
            uid = item.get('unit_id')
            quote = item.get('quote')
            if uid not in ids:
                ids.append(uid)
            if isinstance(quote, str) and quote not in quotes:
                quotes.append(quote)
    return (ids, quotes)","

","def pb_add(out, term, support_ids):
    support = pb_unique(support_ids)
    for row in out:
        if row.get('term') == term and row.get('support_ids', []) == support:
            return
    out.append({'term': term, 'support_ids': support})","

","def pb_union(items):
    if not items:
        return None
    value = items[len(items) - 1]
    i = len(items) - 2
    while i >= 0:
        value = ['participant_union', items[i], value]
        i -= 1
    return value","

","def pb_role_terms(raw, owner_choice):
    text = raw.casefold()
    direct = ['receiving_party']
    controlled = ['affiliates_of', ['receiving_party']]
    default_owner = controlled if owner_choice == 'controlled_company_people' else direct
    items = []
    employee_owner = controlled if owner_choice == 'mixed_recipient_and_controlled_company_people' and ('companies directly or indirectly owned or controlled' in text or 'legal entity that it controls' in text or 'under common control' in text) else default_owner
    if 'employee' in text or 'staff' in text or 'personnel' in text:
        items.append(['employees_of', employee_owner])
    if 'director' in text:
        items.append(['directors_of', default_owner])
    if 'officer' in text or 'official' in text:
        items.append(['officers_of', default_owner])
    if 'independent consultant' in text or 'consultant' in text:
        items.append(['consultants_of', default_owner])
    if 'contractor' in text:
        items.append(['independent_contractors_of', default_owner])
    if 'legal advisor' in text or 'legal adviser' in text or 'attorney' in text or ('legal counsel' in text):
        items.append(['legal_advisors_of', default_owner])
    if 'financial advisor' in text or 'financial adviser' in text:
        items.append(['financial_advisors_of', default_owner])
    if 'professional advisor' in text or 'professional adviser' in text or ('advisor' in text and 'legal advisor' not in text and ('financial advisor' not in text)) or ('adviser' in text and 'legal adviser' not in text and ('financial adviser' not in text)):
        items.append(['professional_advisors_of', default_owner])
    if 'accountant' in text:
        items.append(['accountants_of', default_owner])
    if 'agent' in text:
        items.append(['agents_of', default_owner])
    if 'lender' in text or 'finance provider' in text:
        items.append(['lenders_of', default_owner])
    if not items and 'representative' in text:
        items.append(['representatives_of', default_owner])
    return pb_unique(items)","

","def pb_conditions(need, safeguard, extent):
    items = []
    if isinstance(need, dict) and need.get('choice') == 'need_to_know_required':
        items.append(['need_to_know', pb_quote(need)])
    if isinstance(safeguard, dict) and safeguard.get('choice') in ('written_confidentiality_required', 'confidentiality_required_without_separate_written_agreement'):
        items.append(['confidentiality_bound', pb_quote(safeguard)])
    if isinstance(extent, dict) and extent.get('choice') == 'extent_necessary_required':
        items.append(['extent_necessary', pb_quote(extent)])
    if not items:
        return ['no_condition']
    value = items[0]
    i = 1
    while i < len(items):
        value = ['and_condition', value, items[i]]
        i += 1
    return value","

","def pb_actor(raw):
    text = raw.casefold()
    if 'volunteer' in text:
        return ['named_recipient', 'Volunteer']
    if 'auditor' in text and 'receiving party' not in text:
        return ['named_recipient', 'Auditor']
    if 'visitor' in text and 'receiving party' not in text:
        return ['named_recipient', 'Visitor']
    return ['receiving_party']","

","def pb_trigger(answer):
    if not isinstance(answer, dict):
        return None
    choice = answer.get('choice')
    if choice in ('action_not_present', 'no_trigger_stated_in_window', 'unknown'):
        return None
    if choice == 'request_only':
        return ['request_by', ['disclosing_party']]
    if choice == 'agreement_termination_only':
        return ['agreement_termination']
    if choice == 'relationship_termination_only':
        return ['relationship_termination']
    if choice == 'project_termination_only':
        return ['project_termination']
    if choice == 'service_termination_only':
        return ['service_termination']
    if choice == 'relationship_nonformation_only':
        return ['relationship_nonformation_deadline']
    if choice == 'agreement_termination_or_request':
        return ['trigger_alternative', ['agreement_termination'], ['request_by', ['disclosing_party']]]
    if choice == 'relationship_termination_or_request':
        return ['trigger_alternative', ['relationship_termination'], ['request_by', ['disclosing_party']]]
    if choice == 'relationship_nonformation_or_request':
        return ['trigger_alternative', ['relationship_nonformation_deadline'], ['request_by', ['disclosing_party']]]
    if choice == 'other_explicit_trigger':
        return ['source_stated_trigger', pb_quote(answer)]
    return None","

","def pb_disposal_action(choice, material, raw):
    returned = ['return_to', material, ['disclosing_party']]
    destroyed = ['destroy', material]
    if choice == 'return_only':
        return returned
    if choice == 'destroy_only':
        return destroyed
    if choice == 'return_or_destroy_alternative':
        return ['action_alternative', returned, destroyed]
    if choice == 'return_or_authorized_destroy':
        return ['authorized_action_alternative', returned, destroyed, raw]
    if choice == 'return_and_destroy_distinct_scopes':
        return ['action_conjunction', returned, destroyed]
    return None","

","def pb_suffix(qid):
    parts = qid.split('__', 1)
    return parts[1] if len(parts) == 2 else ''","

","def pb_quote(answer):
    ids, quotes = pb_evidence(answer)
    if quotes:
        return quotes[0]
    return ''","

","def pb_has_root(out, name):
    for row in out:
        term = row.get('term')
        if isinstance(term, list) and term and (term[0] == name):
            return True
    return False","

","def pb_owner(role, choice):
    recipient = ['receiving_party']
    controlled = ['controlled_entities_of', ['receiving_party']]
    if choice == 'controlled_entity_owned_all':
        return controlled
    if choice == 'recipient_and_controlled_same_roles':
        return ['participant_union', recipient, controlled]
    if choice == 'controlled_employees_recipient_professionals' and role == 'employee':
        return controlled
    return recipient","

","def pb_roles(role_choice, owner_choice, raw):
    if role_choice in ('other_explicit_role_set', 'no_recipient_roles_stated') or owner_choice in ('other_mixed_owner_binding', 'owner_not_stated_in_window'):
        if role_choice == 'no_recipient_roles_stated':
            return []
        return [['source_recipient_class', role_choice, owner_choice, raw]]
    text = raw.casefold()
    items = []
    if role_choice in ('employees_only', 'employees_and_contractors', 'employees_and_consultants_or_advisers', 'employees_and_agents', 'employees_and_multiple_professionals'):
        items.append(['employees_of', pb_owner('employee', owner_choice)])
    if role_choice == 'employees_and_contractors' or 'contractor' in text:
        items.append(['independent_contractors_of', pb_owner('professional', owner_choice)])
    if role_choice in ('employees_and_consultants_or_advisers', 'employees_and_multiple_professionals', 'professionals_without_employees'):
        if 'consultant' in text:
            items.append(['consultants_of', pb_owner('professional', owner_choice)])
        if 'adviser' in text or 'advisor' in text:
            items.append(['professional_advisors_of', pb_owner('professional', owner_choice)])
    if role_choice in ('employees_and_agents', 'employees_and_multiple_professionals', 'professionals_without_employees') and 'agent' in text:
        items.append(['agents_of', pb_owner('professional', owner_choice)])
    if 'legal adviser' in text or 'legal advisor' in text or 'attorney' in text:
        items.append(['legal_advisors_of', pb_owner('professional', owner_choice)])
    if 'financial adviser' in text or 'financial advisor' in text:
        items.append(['financial_advisors_of', pb_owner('professional', owner_choice)])
    if 'accountant' in text:
        items.append(['accountants_of', pb_owner('professional', owner_choice)])
    if role_choice == 'representatives_by_definition':
        items.append(['representatives_of', ['receiving_party']])
    return pb_unique(items)","

","def pb_material(answer):
    if not isinstance(answer, dict) or answer.get('choice') in ('action_not_present', 'unknown'):
        return None
    return ['source_disposal_material', answer.get('choice'), pb_quote(answer)]","

","def pb_same(a, b):
    return a == b and a is not None","

","def pb_support(answers):
    ids = []
    for answer in answers:
        more, quotes = pb_evidence(answer)
        ids = pb_unique(ids + more)
    return ids","

","def previous_compose(inputs, premises):
    out = []
    unresolved = []
    source_output = inputs.get('source_output', {})
    if isinstance(source_output, dict):
        for row in source_output.get('statements', []):
            if isinstance(row, dict) and isinstance(row.get('term'), list):
                pb_add(out, row.get('term'), row.get('support_ids', []))
        for item in source_output.get('unresolved', []):
            if isinstance(item, str) and item not in unresolved:
                unresolved.append(item)
    rows = pb_rows(inputs.get('semantic_answers', []))
    for effect in rows:
        if not isinstance(effect, dict) or effect.get('operation') != 'disclosure_norm_effect_v2':
            continue
        if effect.get('choice') in ('unknown', 'not_an_operative_disclosure_norm'):
            continue
        suffix = pb_suffix(effect.get('id', ''))
        roles = pb_answer(rows, 'disclosure_disclosure_recipient_roles_v2__' + suffix)
        owner = pb_answer(rows, 'disclosure_disclosure_recipient_owner_v2__' + suffix)
        need = pb_answer(rows, 'disclosure_need_to_know_requirement_v2__' + suffix)
        safeguard = pb_answer(rows, 'disclosure_confidentiality_safeguard_v2__' + suffix)
        extent = pb_answer(rows, 'disclosure_extent_necessity_requirement_v2__' + suffix)
        answers = [effect, roles, owner, need, safeguard, extent]
        ids = pb_support(answers)
        raw = pb_quote(roles) or pb_quote(effect)
        role_choice = roles.get('choice') if isinstance(roles, dict) else None
        owner_choice = owner.get('choice') if isinstance(owner, dict) else None
        actor = pb_actor(pb_quote(effect))
        recipients = pb_union(pb_roles(role_choice, owner_choice, raw)) if role_choice and owner_choice else None
        if effect.get('choice') == 'elliptical_recipient_confidentiality_scope':
            if recipients is not None:
                pb_add(out, ['elliptical_recipient_confidentiality_scope', actor, recipients, pb_quote(effect)], ids)
            continue
        if recipients is None or not all((isinstance(x, dict) and x.get('choice') != 'unknown' for x in (roles, owner, need, safeguard, extent))):
            unresolved.append('disclosure fields unresolved for ' + suffix)
            continue
        permission = ['permission', actor, ['disclose', ['confidential_information'], recipients], pb_conditions(need, safeguard, extent)]
        if effect.get('choice') == 'operative_permission':
            pb_add(out, permission, ids)
        elif effect.get('choice') == 'prohibition_with_class_permission':
            pb_add(out, ['prohibition', actor, ['disclose', ['confidential_information'], ['third_parties']], ['no_condition'], ['exception_set', ['permission_exception', permission]]], ids)
        elif effect.get('choice') == 'operative_prohibition_only':
            pb_add(out, ['prohibition', actor, ['disclose', ['confidential_information'], ['third_parties']], ['no_condition'], ['no_exceptions']], ids)
    for connection in rows:
        if not isinstance(connection, dict) or connection.get('operation') != 'disposal_action_connection_v2':
            continue
        if connection.get('choice') in ('unknown', 'not_a_disposal_action'):
            continue
        suffix = pb_suffix(connection.get('id', ''))
        rt = pb_answer(rows, 'disposal_return_trigger_binding_v1__' + suffix)
        dt = pb_answer(rows, 'disposal_destroy_trigger_binding_v1__' + suffix)
        rm = pb_answer(rows, 'disposal_return_material_scope_v1__' + suffix)
        dm = pb_answer(rows, 'disposal_destroy_material_scope_v1__' + suffix)
        retention = pb_answer(rows, 'disposal_post_disposal_retention_effect_v2__' + suffix)
        answers = [connection, rt, dt, rm, dm, retention]
        ids = pb_support(answers)
        actor = pb_actor(pb_quote(connection))
        return_trigger = pb_trigger(rt)
        destroy_trigger = pb_trigger(dt)
        return_material = pb_material(rm)
        destroy_material = pb_material(dm)
        return_action = ['return_to', return_material, ['disclosing_party']] if return_material is not None else None
        destroy_action = ['destroy', destroy_material] if destroy_material is not None else None
        choice = connection.get('choice')
        emitted = False
        if choice == 'return_only' and return_action is not None and (return_trigger is not None):
            pb_add(out, ['disposal_obligation', actor, return_action, return_trigger, ['no_exceptions']], ids)
            emitted = True
        elif choice == 'destroy_only' and destroy_action is not None and (destroy_trigger is not None):
            pb_add(out, ['disposal_obligation', actor, destroy_action, destroy_trigger, ['no_exceptions']], ids)
            emitted = True
        elif choice in ('return_or_destroy_alternative', 'return_or_authorized_destroy') and return_action is not None and (destroy_action is not None):
            if pb_same(return_trigger, destroy_trigger):
                if choice == 'return_or_destroy_alternative':
                    action = ['action_alternative', return_action, destroy_action]
                    exceptions = ['no_exceptions']
                else:
                    action = ['authorized_action_alternative', return_action, destroy_action, pb_quote(connection)]
                    exceptions = ['exception_set', ['authorization_exception', pb_quote(connection)]]
                pb_add(out, ['disposal_obligation', actor, action, return_trigger, exceptions], ids)
                emitted = True
            elif return_trigger is not None and destroy_trigger is not None:
                pb_add(out, ['disposal_obligation', actor, return_action, return_trigger, ['no_exceptions']], ids)
                exceptions = ['exception_set', ['authorization_exception', pb_quote(connection)]] if choice == 'return_or_authorized_destroy' else ['no_exceptions']
                pb_add(out, ['disposal_obligation', actor, destroy_action, destroy_trigger, exceptions], ids)
                emitted = True
        elif choice == 'return_and_destroy_distinct_scopes' and return_action is not None and (destroy_action is not None):
            if pb_same(return_trigger, destroy_trigger):
                pb_add(out, ['disposal_obligation', actor, ['action_conjunction', return_action, destroy_action], return_trigger, ['no_exceptions']], ids)
                emitted = True
            elif return_trigger is not None and destroy_trigger is not None:
                pb_add(out, ['disposal_obligation', actor, return_action, return_trigger, ['no_exceptions']], ids)
                pb_add(out, ['disposal_obligation', actor, destroy_action, destroy_trigger, ['no_exceptions']], ids)
                emitted = True
        if not emitted:
            unresolved.append('disposal fields unresolved for ' + suffix)
        if isinstance(retention, dict) and retention.get('choice') in ('explicit_retention_permission', 'both_permission_and_prohibition'):
            pb_add(out, ['retention_permission', actor, ['source_retention_material', pb_quote(retention)], ['after_disposal'], ['retention_condition', pb_quote(retention)]], ids)
        if isinstance(retention, dict) and retention.get('choice') in ('explicit_retention_prohibition', 'both_permission_and_prohibition'):
            pb_add(out, ['retention_prohibition', actor, ['source_retention_material', pb_quote(retention)], ['after_disposal']], ids)
    disclosure_locator = pb_answer(rows, 'positive_disclosure_locator_v2')
    if isinstance(disclosure_locator, dict) and disclosure_locator.get('choice') == 'none_in_complete_source' and (not pb_has_root(out, 'permission')) and (not pb_has_root(out, 'prohibition')):
        ids, quotes = pb_evidence(disclosure_locator)
        pb_add(out, ['complete_source_no_disclosure_permission'], ids)
    disposal_locator = pb_answer(rows, 'positive_disposal_locator_v2')
    if isinstance(disposal_locator, dict) and disposal_locator.get('choice') == 'none_in_complete_source' and (not pb_has_root(out, 'disposal_obligation')):
        ids, quotes = pb_evidence(disposal_locator)
        pb_add(out, ['complete_source_no_disposal_obligation'], ids)
    return {'statements': out, 'complete': len(pb_unique(unresolved)) == 0, 'unresolved': pb_unique(unresolved)}","

","def compose_unique(values):
    out = []
    for value in values:
        if value not in out:
            out.append(value)
    return out","

","def compose_add(out, term, support_ids):
    support = compose_unique(support_ids)
    for row in out:
        if row.get('term') == term and row.get('support_ids', []) == support:
            return
    out.append({'term': term, 'support_ids': support})","

","def compose_rows(value):
