","def pa_rows(value):
    if isinstance(value, list):
        return value
    if isinstance(value, dict):
        rows = value.get('answers')
        if isinstance(rows, list):
            return rows
        if isinstance(rows, dict):
            return list(rows.values())
        return list(value.values())
    return []","

","def pa_answer(rows, qid):
    for row in rows:
        if isinstance(row, dict) and row.get('id') == qid:
            return row
    return None","

","def pa_evidence_ids(answer):
    out = []
    if not isinstance(answer, dict):
        return out
    evidence = answer.get('evidence', [])
    if isinstance(evidence, dict):
        evidence = [evidence]
    for item in evidence:
        if isinstance(item, dict):
            uid = item.get('unit_id')
            if uid not in out:
                out.append(uid)
    return out","

","def pa_low(value):
    if not isinstance(value, str):
        value = str(value)
    return value.casefold()","

","def pa_any(text, parts):
    for part in parts:
        if part in text:
            return True
    return False","

","def pa_disclosure_candidate(text):
    t = pa_low(text)
    roles = pa_any(t, ['employee', 'staff', 'personnel', 'contractor', 'consultant', 'adviser', 'advisor', 'agent', 'representative', 'officer', 'director'])
    effect = pa_any(t, ['may disclose', 'may be disclosed', 'will disclose', 'disclosed only', 'restrict access', 'restrict disclosure', 'except in confidence', 'except its employees', 'only to such employees', 'only to employees', 'not to disclose'])
    elliptical = 'confiden' in t and 'need to know' in t and roles
    return roles and (effect or elliptical)","

","def pa_disposal_candidate(text):
    t = pa_low(text)
    action = pa_any(t, ['return', 'destroy', 'destruction', 'delete', 'erase'])
    material = pa_any(t, ['confidential information', 'such information', 'all information', 'copies', 'copy', 'materials', 'documents', 'records', 'reproductions'])
    return action and material","

","def pa_positions(spans, kind, seed_ids):
    seed = set(seed_ids)
    out = []
    i = 0
    while i < len(spans):
        text = spans[i].get('text', '')
        match = pa_disclosure_candidate(text) if kind == 'disclosure' else pa_disposal_candidate(text)
        if match:
            out.append(i)
        elif spans[i].get('id') in seed:
            if kind == 'disclosure' and pa_any(pa_low(text), ['disclos', 'access', 'confiden']):
                out.append(i)
            if kind == 'disposal' and pa_any(pa_low(text), ['return', 'destroy', 'delete', 'erase']):
                out.append(i)
        i += 1
    return sorted(set(out))","

","def pa_windows(spans, positions, kind):
    groups = []
    for pos in positions:
        if not groups or pos - groups[len(groups) - 1][len(groups[len(groups) - 1]) - 1] > 1:
            groups.append([pos])
        else:
            groups[len(groups) - 1].append(pos)
    out = []
    for group in groups:
        before = 2
        after = 2 if kind == 'disclosure' else 4
        start = max(0, group[0] - before)
        stop = min(len(spans) - 1, group[len(group) - 1] + after)
        ids = []
        i = start
        while i <= stop:
            ids.append(spans[i].get('id'))
            i += 1
        out.append(ids)
    return out","

","def pa_add(queries, rows, qid, operation, unit_ids):
    if unit_ids and pa_answer(rows, qid) is None:
        queries.append({'id': qid, 'operation': operation, 'unit_ids': unit_ids})","

","def pa_add_fields(queries, rows, windows, prefix, operations):
    for ids in windows:
        if not ids:
            continue
        suffix = str(ids[0]) + '_' + str(ids[len(ids) - 1])
        for operation in operations:
            pa_add(queries, rows, prefix + operation + '__' + suffix, operation, ids)","

","def _scope_previous_plan(inputs, premises):
    spans = []
    for span in inputs.get('source_spans', []):
        if isinstance(span, dict):
            spans.append(span)
    if not spans:
        return {'queries': []}
    all_ids = []
    for span in spans:
        all_ids.append(span.get('id'))
    rows = pa_rows(inputs.get('semantic_answers', []))
    queries = []
    disclosure_id = 'positive_disclosure_locator_v2'
    disposal_id = 'positive_disposal_locator_v2'
    disclosure = pa_answer(rows, disclosure_id)
    disposal = pa_answer(rows, disposal_id)
    pa_add(queries, rows, disclosure_id, 'positive_disclosure_locator_v2', all_ids)
    pa_add(queries, rows, disposal_id, 'positive_disposal_locator_v2', all_ids)
    disclosure_seed = pa_evidence_ids(disclosure) if isinstance(disclosure, dict) and disclosure.get('choice') == 'candidate_found' else []
    disposal_seed = pa_evidence_ids(disposal) if isinstance(disposal, dict) and disposal.get('choice') == 'candidate_found' else []
    disclosure_windows = pa_windows(spans, pa_positions(spans, 'disclosure', disclosure_seed), 'disclosure')
    disposal_windows = pa_windows(spans, pa_positions(spans, 'disposal', disposal_seed), 'disposal')
    pa_add_fields(queries, rows, disclosure_windows, 'disclosure_', ['disclosure_norm_effect_v2', 'disclosure_recipient_roles_v2', 'disclosure_recipient_owner_v2', 'need_to_know_requirement_v2', 'confidentiality_safeguard_v2', 'extent_necessity_requirement_v2'])
    pa_add_fields(queries, rows, disposal_windows, 'disposal_', ['disposal_action_connection_v2', 'return_trigger_binding_v1', 'destroy_trigger_binding_v1', 'return_material_scope_v1', 'destroy_material_scope_v1', 'post_disposal_retention_effect_v2'])
    return {'queries': queries}","
