","def atoms_reference_labels(raw):
    text = atoms_low(raw)
    out = []
    start = 0
    while start < len(text):
        pos = text.find('clause ', start)
        if pos < 0:
            break
        i = pos + 7
        j = i
        while j < len(text) and (text[j].isdigit() or text[j] == '.'):
            j += 1
        token = text[i:j]
        while token.endswith('.'):
            token = token[:-1]
        if token and '.' in token:
            parts = token.split('.')
            valid = True
            for part in parts:
                if not part.isdigit():
                    valid = False
            if valid and token not in out:
                out.append(token)
        start = max(j, pos + 8)
    return out","

